INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 3, 'theory', 'Quiz: systemd');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 0, 'app.service has Requires=db.service and After=db.service. The db.service unit failed to start. What happens to app.service?', '["It starts as usual: Requires does not check the result", "It starts later, after db.service is retried", "It will not be started, because the required unit failed and an order is set", "systemd reboots the server"]', 2, 'If a required unit fails to start and an After ordering on it is set, the dependent unit is not started. Without After it would start in parallel and would not wait for the result of db. With Wants instead of Requires it would simply survive the failure of db.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 1, 'How do you correctly replace a service''s start command in a drop-in rather than add a second one?', '["Write ExecStart= with an empty value, then a new ExecStart=", "Write one more ExecStart= line with the new command", "Edit the file in /usr/lib/systemd/system directly", "Write ExecStart=none"]', 0, 'ExecStart is a list setting: an empty assignment resets the accumulated list. A plain second line gives an ordinary service two commands, which is allowed only for oneshot, and the unit will not load.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 2, 'What does Persistent=true do in a timer with OnCalendar?', '["Keeps the timer from being disabled on reboot", "Runs the service every minute", "Forbids starting the service by hand", "Stores the time of the last run and catches up a missed run when the machine comes back"]', 3, 'Persistent stores the time of the last trigger on disk. If the machine was off at the scheduled time, the missed run happens right after startup. It works only with OnCalendar.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 3, 'A service with Restart=on-failure exited with code 0. What will systemd do?', '["Restart it, as after any exit", "Not restart it: a clean exit is not a failure", "Mark the unit failed and restart it in a minute", "Restart it, but only after a manual reset-failed"]', 1, 'on-failure reacts to a nonzero code, an unclean signal, a timeout and the watchdog. Code 0 is a clean exit; only always (and on-success) restart such a service.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 3, 4, 'What does the number after the plus mean in a systemd-analyze critical-chain line?', '["The moment the unit was stopped", "How much memory the unit used", "How long the unit took to start", "How many times the unit restarted"]', 2, 'After @ is the time the unit became active or started, and after + is how long the start of the unit took. This command shows neither memory nor the restart counter.');
